mapper.select:
/* com.heeji.picket.mapper.SeatMapper.selectedSeatList */ SELECT S.SEAT_ID AS seatId , S.SEAT_GRADE_ID AS seatGradeId , S.SHOW_DATE_ID AS showDateId , S.SHOW_ID AS showId , S.SEAT_NUMBER AS seatNumber , S.SEAT_STATUS AS seatStatus , S.BOOKED_NUMBER AS bookedNumber , S.BOOKED_DATE AS bookedDate , S.BOOKED_ID AS bookedId , SG.GRADE_NAME AS gradeName , SG.PRICE AS price FROM SEAT S LEFT JOIN SEAT_GRADE SG ON S.SEAT_GRADE_ID = SG.SEAT_GRADE_ID WHERE 1 = 1 AND S.SEAT_ID IN
#{arr}
ORDER BY SG.SEAT_GRADE_ID ASC, S.SEAT_NUMBER ASC

mapper.update:
/* com.heeji.picket.mapper.SeatMapper.book */
UPDATE  SEAT
SET     SEAT_STATUS   = 'booked'
,       BOOKED_ID     = #{bookedId}
,       BOOKED_NUMBER = #{bookedNumber}
,       BOOKED_DATE   = NOW()
WHERE   SEAT_STATUS = 'available'
AND     SEAT_ID IN

    #{arr}

mapper.select:
/* com.heeji.picket.mapper.SeatMapper.myTicketCnt */
SELECT  COUNT(DISTINCT S.BOOKED_NUMBER)
FROM    SEAT S
WHERE   S.BOOKED_ID = #{userId}
AND     S.SEAT_STATUS = 'booked'
AND     S.BOOKED_NUMBER IS NOT NULL

/* com.heeji.picket.mapper.SeatMapper.bookedCountByShowId */
SELECT  COUNT(*)
FROM    SEAT
WHERE   SHOW_ID = #{showId}
AND     SEAT_STATUS = 'booked'
